package nl.voetbalhub.app;
import android.app.Activity;
import android.webkit.*;
import android.widget.FrameLayout;
import org.json.*;
/** Home uses exactly the shared central shirt renderer and rights-checked match overview. */
public final class MatchStrip40 extends FrameLayout {
 private static final java.util.concurrent.ExecutorService IO=java.util.concurrent.Executors.newFixedThreadPool(1);
 private final Activity a;private final WebView web;private final Runnable action;private boolean attached,ready,loading;private JSONObject snapshot;private long lastAttempt;
 private final Runnable refresh=new Runnable(){public void run(){if(!attached)return;if(getWindowVisibility()==VISIBLE&&hasWindowFocus())load();postDelayed(this,60000);}};
 public MatchStrip40(Activity a,Runnable action){super(a);this.a=a;this.action=action;web=new WebView(a);web.setBackgroundColor(0xFF030605);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setAllowFileAccess(true);web.getSettings().setAllowContentAccess(false);web.getSettings().setAllowFileAccessFromFileURLs(false);web.getSettings().setAllowUniversalAccessFromFileURLs(false);web.addJavascriptInterface(new Bridge(),"MatchStrip50");web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}@Override public void onPageFinished(WebView v,String url){if("file:///android_asset/match-strip50.html".equals(url)){ready=true;render();}}@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){if(!"file".equals(r.getUrl().getScheme())&&!"data".equals(r.getUrl().getScheme()))return new WebResourceResponse("text/plain","UTF-8",new java.io.ByteArrayInputStream(new byte[0]));return null;}});addView(web,new LayoutParams(-1,PremiumDesign40.dp(a,140)));try{snapshot=new JSONObject(a.getSharedPreferences("veldio_tools39",0).getString("matchOverview50","{}"));}catch(Exception ignored){}web.loadUrl("file:///android_asset/match-strip50.html");}
 private final class Bridge{@JavascriptInterface public void open(){a.runOnUiThread(()->{if(attached)action.run();});}}
 private void load(){if(loading||System.currentTimeMillis()-lastAttempt<60000)return;loading=true;lastAttempt=System.currentTimeMillis();IO.execute(()->{JSONObject data=null;try{JSONObject r=new JSONObject(DeadlineHttp.get("https://voetbalhub-redactie.onrender.com/integrations/football?competition=eredivisie&view=veldio50",14000,2000000));if(PublicationPolicy.allows(r))data=r;}catch(Exception ignored){}final JSONObject result=data;a.runOnUiThread(()->{loading=false;if(!attached)return;if(result!=null){snapshot=result;a.getSharedPreferences("veldio_tools39",0).edit().putString("matchOverview50",result.toString()).apply();}render();});});}
 private void render(){if(!ready)return;JSONArray visible=new JSONArray();if(snapshot!=null&&PublicationPolicy.allows(snapshot)){JSONArray fs=snapshot.optJSONArray("fixtures"),eu=snapshot.optJSONArray("europeanFixtures");long now=System.currentTimeMillis();java.time.LocalDate today=java.time.Instant.ofEpochMilli(now).atZone(java.time.ZoneId.of("Europe/Amsterdam")).toLocalDate();for(JSONArray rows:new JSONArray[]{fs,eu})if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject f=rows.optJSONObject(i);try{if(f!=null&&java.time.Instant.parse(f.getString("date")).atZone(java.time.ZoneId.of("Europe/Amsterdam")).toLocalDate().equals(today)&&!java.util.Arrays.asList("TBD","PST","CANC").contains(f.optString("status")))visible.put(f);}catch(Exception ignored){}}}web.evaluateJavascript("window.setMatches50("+visible.toString()+")",null);}
 @Override protected void onAttachedToWindow(){super.onAttachedToWindow();attached=true;post(refresh);}
 @Override protected void onDetachedFromWindow(){attached=false;ready=false;removeCallbacks(refresh);web.removeJavascriptInterface("MatchStrip50");web.stopLoading();web.destroy();super.onDetachedFromWindow();}
}
